const empty="       ...       ....        nothing printing :(";
pub export fn magicdiamondpattern(n:i64,out:[*c]u8,cap:usize)i64{if(n>45)return -1;if(n<=0){if(out==null or cap<empty.len)return -2;for(0..empty.len)|i|out[i]=empty[i];return empty.len;}const s:usize=@intCast(n);const need=3*s*s+4*s;if(out==null or cap<need)return -2;var p:usize=0;for(0..s)|i|{for(0..s-i-1)|_|{out[p]=' ';p+=1;}for(0..i+1)|_|{out[p]='*';p+=1;out[p]=' ';p+=1;}out[p]='\n';p+=1;}var i=s;while(i>0){i-=1;for(0..i+1)|_|{out[p]='*';p+=1;out[p]=' ';p+=1;}out[p]='\n';p+=1;for(0..s-i)|_|{out[p]=' ';p+=1;}}return @intCast(p);}
